function load() {
    sd = (i, month = 'long') => {
        let date = new Date(2020, 0, 1);
        date.setDate(date.getDate() + i);
        return date.toLocaleString('ru-RU', { day: 'numeric', month })
    }
    f = q => [formatNumber(q, 2), q]
    d = []
    labels = []
    va = [[], []]
    for (i = 0; i < data.length / 2; i++) {
        min = data[2 * i]
        max = data[2 * i + 1]
        va[0].push(min)
        va[1].push(max)
        labels.push(sd(i, 'short'))
        d.push([[sd(i), i], min, max, f(max - min), f((max + min) / 2)])
    }
    q = va.map(e => [Math.min(...e), Math.max(...e)].map(i => e.indexOf(i)))
    mi = [0, 3, 1, 2].map(e => q[Math.floor(e / 2)][e % 2])
    m = mi.map((_, e) => va[e % 2][mi[e]])

    s = ['абсолютный минимум', 'абсолютный максимум', 'максимальный минимум', 'минимальный максимум', 'абс. макс. - абс. мин.'].reduce((a, e, i) => a + `<tr><td>`
        + (i == 4 ? [e, '-', formatNumber(m[1] - m[0], 1)] : [e, sd(mi[i]), m[i]]).join('<td>'), `<table class='table_border table_color'><thead><tr><td><th>дата<th>T</thead>`) + `</table>`

    //console.log(mi[1], d.length / 2)
    x = [[], []]
    delta = 32
    for (i = mi[0]; i < mi[0] + d.length / 2; i++) {
        for (j = i + delta; j < mi[0] + d.length / 2; j++) {
            if (d[i][1] > d[j][1])
                x[0].push([j, i])//not [i,j]
        }
    }

    for (i = mi[0] + d.length / 2; i < d.length; i++) {
        for (j = i + delta; j < d.length; j++) {
            if (d[i][1] < d[j][1])
                x[0].push([i, j])
        }
    }

    for (i = mi[1]; i < d.length; i++) {
        for (j = i + delta; j < d.length; j++) {
            if (d[i][2] < d[j][2])
                x[1].push([i, j])
        }
    }

    for (i = mi[1] - d.length / 2; i < mi[1]; i++) {
        for (j = i + delta; j < mi[1]; j++) {
            if (d[i][2] > d[j][2])
                x[1].push([i, j])
        }
    }

    const td = `<td style='vertical-align:top;max-width:390px;'>`
    // x=x.slice(0,10)
    p = x.map((e, i) => e.map(e => [...e.map(e => sd(e) + ' ' + d[e][i + 1]), Math.abs(e[1] - e[0])]))
    mm = ['минимум', 'максимум']
    t1 = ['День1 более далёкий от самого холодного имеющий минимум ниже, чем более близкий день2.', 'День1 более далёкий от самого тёплого имеющий максимум выше, чем более близкий день2.']
    p.forEach((e, i) => {
        t2 = p.map((_, j) => `день${j + 1} ` + mm[i])
        t2.push(`разница<br>в днях`)
        s += td + t1[i] + new Table(t2, e, "bcs21").html()
    })

    el('p', `<p id='g'></p><table><tr><td>` + new Table(['день', 'мин', 'макс', 'макс-мин', '(макс+мин)/2'], d, "bcs").html() + `${td + s}</table>`)

    //createNGraphs('g', ['минимум', 'максимум'], labels, va, { width: 1600, type: 'line', ticksOnlyFirst: 1, borderWidth: 2, sameScale: 1 })
    createScatterGraph('g', ['минимум', 'максимум'], labels, va, 1600, "График минимумов и максимумов.")
}

function createScatterGraph(id, names, labels, a, width, title) {
    const clr = ['rgba(255,0,0,0.5)', 'rgba(75, 192, 192, 1)']
    let d = a.map(e => e.map((y, x) => ({ x, y })))
        , b = a.flat()
        , datasets = names.map((label, i) => {
            let c = clr[i % clr.length]
            return {
                type: 'scatter',
                label,
                data: d[i],
                pointRadius: 2,
                borderColor: c,
                backgroundColor: c,
                pointBackgroundColor: c
            }
        })

    createChart(id, width, {
        type: 'scatter',
        data: {
            labels, datasets
        },
        options: {
            scales: {
                x: {
                    position: 'bottom',
                    type: 'category',
                    display: true
                },
                y: {
                    min: Math.floor(Math.min(...b)) - 1,
                    max: Math.ceil(Math.max(...b)) + 1,
                    ticks: {
                        stepSize: 2,
                    }
                }
            },
            plugins: {
                title: {
                    display: true,
                    text: title
                }
            }
        }
    })
}

